def invert_row_column(grid, row, column, direction):
    width = len(grid[0])
    if direction == 'row':
        for i in range(width):
            if i / width == row:
                for j in range(column, width):
                    grid[row][j], grid[row][0] = '0', '1' if grid[row][j] == '1' else '0'
            else:
                for j in range(column, width):
                    grid[row][j], grid[row][width - 1] = '0', '1' if grid[row][j] == '1' else '0'
    elif direction == 'column':
        for i in range(row, len(grid)):
            for j in range(column, width):
                grid[i][j], grid[0][j] = '0', '1' if grid[i][j] == '1' else '0'
        for i in range(row, len(grid)):
            for j in range(column, width):
                grid[i][j], grid[width - 1][j] = '0', '1' if grid[i][j] == '1' else '0'

def solve(H, W, S):
