from typing import List

def enhanced_fibonacci(n: int, mod: int = 1000000009) -> int:
    """
    Finds the nth term in the enhanced Fibonacci sequence (F_n) modulo mod.
    The sequence F_1 = 1, F_2 = 1, and for n > 2, F_n = F_(n-1) + F_(n-2).
    """
    if n == 1 or n == 2:
        return 1
    a, b = 1, 1
    for _ in range(4, n + 1):
        a, b = b, (a + b) % mod
    return a

def solve_queries(n: int, m: int, queries: List[List[int]]) -> None:
    valid_queries = [query for query in queries if query[0] == 1]
    a = [0] + list(map(int, input().split()))
    results = []

    for query in valid_queries:
        l, r = query
        if query[0] == 1:
            for i in range(l - 1, r):
                a[l - 1] = (a[l - 1] + enhanced_fibonacci(r - l + 2)) % 1000000009
        elif query[0] == 2:
            results.append(enhanced_fibonacci(r) - enhanced_fibonacci(l - 1) + 1000000009)  # Adding 1000000009 here to counteract modulo 1000000009 for subtraction

    for result in results:
        print(result % 1000000009)

