from collections import defaultdict, deque
from typing import List

def validOrdering(n: int, k: int, preq, pairs) -> List[int]:
    # Build prerequisites graph
    graph = defaultdict(list)
    indegree = [0] * (n + 1)
    for i in range(1, n + 1):
        graph[preq[i]].append(i)

    # Initialize deque for topological sort
    ordering = []
    if n == 1:
        return [1]

    for i in range(1, n + 1):
        if indegree[i] == 0:
            ordering.append(i)

    # Process pairs
    for x, y in pairs:
        if indegree[x] != 0 or indegree[y] != 0:
            return []
        indegree[x] -= 1
        indegree[y] -= 1
        graph[x].append(y)
        graph[y].append(x)

    # Maintain order ends when all walks are processed
    while True:
        next_step = []
        wiring_flag = 0
        while ordering:
            cur = ordering.pop()
            for nxt in graph[cur]:
                if indegree[nxt] > 0:
                    wiring_flag = 1
                    ordering.append(nxt)
                    next_step.append(nxt)
                    indegree[nxt] -= 1
                    if not wiring_flag and indegree[next_step[-1]] == 0:
                        next_step[-1], next_step[0] = next_step[0], next_step[-1]
                    break
                indegree[nxt] -= 1
                if not wiring_flag and cur == next_step[-1]:
                    wiring_flag = 1
            graph[cur].clear()

        if wiring_flag:
            continue
        elif not next_step:
            if len(ordering) == 0:
                return ordering
            del ordering[-1]
            continue
        else:
            result = []
            for nxt in next_step:
                result.append(nxt)
                if len(ordering) > 0 and nxt == ordering[-1]:
                    result[0], result[-1] = result[-1], result[0]
            return result

if __name__ == "__main__":
    n, k = map(int, input().split())
    preq = list(map(int, input().split()))
    pairs = [list(map(int, input().split())) for _ in range(k)]

    print(" ".join(map(str, validOrdering(n, k, preq, pairs))))
