    min_dist = float('inf')
    for point2 in red_points:
        distance = math.sqrt((point[0] - point2[0])**2 + (point[1] - point2[1])**2)
        if distance < min_dist:
            min_dist = distance
    return min_dist

# Function to check if a circle with radius 'r' contains at least one red point
def contains_red_point(r, blue_points, red_points):
    for point2 in red_points:
        if math.sqrt((point2[0] - blue_points[0][0])**2 + (point2[1] - blue_points[0][1])**2) <= r:
            return True
    return False

