from collections import defaultdict

def dfs(v, parent, d, depth_map):
    depth_map[v] = [0, 0]
    if parent:
        depth_map[v] = [depth_map[parent][1], depth_map[parent][0] + 1]
    for u in G[v]:
        if u != parent:
            depth_map[v] += dfs(u, v, d, depth_map)

def count_paths(d, depth_map):
    pairs = 0
    for v in depth_map:
        i, j = d[v]
        if i != 0 or j != 0:
            pairs += depth_map[v][0] * depth_map[v][1]
    return pairs

def solve(n):
    G = defaultdict(list)
    for i in range(n - 1):
        u, v = map(int, input().split())
        G[u - 1].append(v - 1)
        G[v - 1].append(u - 1)
    depth_maps = [{} for _ in range(n)]
    for v in G:
        dfs(v, None, d, depth_maps)
    return count_paths(d, depth_maps)

