    for tl_i, tr_i, l_i, r_i in [(tl, tr, l, r)] * len(tl):
        if (tl_i <= x <= tr_i) and (l_i <= x <= r_i):
            continue
        if tl_i < x:
            span = x - min(0, tl_i - l_i)  # positive if x is in the left span
            delta = -1 * abs(span * ((x - l_i) / span) - x) if span > 0 else span + 1
        else:
            span = max(0, x - tr_i)  # if x is in the right span (left span needs more energy+displacement)
            delta = abs(span * ((x - tr_i) / span) - x)
        total_energy += delta
    return int(math.ceil((total_energy)))

