from math import factorial

MOD = 10**9 + 7

def power(x, k, M=MOD):
    if k == 0:
        return 1 % M
    half = power(x, k // 2, M)
    if k % 2 == 0:
        return half * half % M
    else:
        return half * half * x % M

def compute_tree_values(n):
    total_value = 0
    for i in range(n):
        total_value += 2**i
    return total_value * (total_value - 1) // 2 % MOD

def main():
    n, k = map(int, input().split())
    adj = defaultdict(list)
    for a, b in [[int(x) for x in input().split()] for _ in range(n-1)]:
        adj[a-1].append(b-1)
        adj[b-1].append(a-1)

    if k == 1:
        print(compute_tree_values(n))
        return

    tree_edges = set((p, q) for p, q in enumerate(list(range(n))))
    early_expansions = {t: 0 for t in tree_edges if len(t) > 1}
    for _, t in early_expansions.items():
        roots = get_roots(adj, t)
        roots.sort()

        sum_roots_k_minus_1 = [0, 0]  # recursion boundary
        results = []

        for p in roots:
            path = get_subtree_path(adj, p)
            # Sum the values of the subtrees that are not disjoint from t
            sum_roots_k_minus_1[0] += sum_roots_k_minus_1[1]
            if len(path) == len(t) - 1:
                q = path[-1]
                sum_roots_k_minus_1.extend(early_expansions[q])
                results.append(early_expansions[q])
            sum_roots_k_minus_1[1] += power(2, len(path) - len(t) + 1)
            results.append(path)
            # adds all parts, that are subsets of or start with t (no counting alternate roots)
            outputs_add_edges = {edge for edge in tree_edges if t & get_roots(adj, edge) or not path & get_roots(adj, edge)}
            for edge in outputs_add_edges:
                result = get_roots(adj, edge) & get_roots(adj, path)
                if result == t:
                    results.append(early_expansions[edge])
            results.extend(sum_roots_k_minus_1)

        ending_results = [[type(value).__name__, value] if isinstance(value, list) else type(value).__name__ for value in results]

        print(''.join([str(end) for end in ending_results]))

def get_roots(graph, t):
    roots = set()
    for node in t:
        for neighbor in graph[node]:
            roots.add(get_roots(graph, set([end for end in t if (neighbor in end) or (ends in t and edge in ends and edge.ends[-1] != ends[-1])])) | {end})
    return roots

def get_subtree_path(adj, t):
    path = []
    while t in adj:
        t = adj[t][0]
        path.append(t)
