# Function to calculate the Fibonacci number using matrix exponentiation
def matrix_pow(matrix: List[List[int]], n: int) -> List[List[int]]:
    size = len(matrix)
    result = [[1, 0], [0, 1]]
    while n:
        if n % 2:
            result = multiply(result, matrix)
        matrix = multiply(matrix, matrix)
        n //= 2
    return result

# Function to multiply two matrices
def multiply(matrix_a: List[List[int]], matrix_b: List[List[int]]) -> List[List[int]]:
    size = len(matrix_a)
    result = [[0 for _ in range(size)] for _ in range(size)]
    for i in range(size):
        for j in range(size):
            for k in range(size):
                result[i][j] += matrix_a[i][k] * matrix_b[k][j]
                result[i][j] %= 1000000009
    return result

# Function to perform necessary computations based on query
def process_query(n: int, matrix: List[List[int]], queries: List[List[int]]) -> List[int]:
    modifications = 0
    answers = [0] * len(queries)
    for query in queries:
        if query[0] == 1:
            # Calculate the difference given by the query and apply it to all affected elements in the array
            modifications += (query[1] - query[2] + 1) * (query[2] - query[1] + 1) // 2
            for j in range(query[1] - 1, query[2]):
                matrix[-1][j] += modifications
        elif query[0] == 2:
            answers[query[1] - 1] = matrix[-1][query[2] - 1]
    return answers

