import sys

def euler_tour(graph, start_vertex):
    stack = [start_vertex]
    visited = set([start_vertex])
    tour = []
    while stack:
        node = stack[-1]
        if node not in graph:
            tour.append(node)
            if len(stack) == 1:
                return tour, visit_time[node]
            stack.pop()
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                stack.append(neighbor)
                break
        else:
            visited.add(node)
            tour.append(node)
            prev_node = stack.pop()
            if len(stack) == 1:
                total_time[node] += total_time[prev_node]
                return tour, total_time[node]
            if total_time[prev_node] > 0:
                edge_weights[prev_node] += total_time[node]
            elif len(tour) < len(graph):
                edge_weights[prev_node] += len(tour) - len(graph)
            total_time.pop(prev_node)
            return tour, total_time[node]

