from math import divmod

MOD = 998244353

def f(B, N):
    if N == 1:
        return next(iter(B))
    elif N == 2:
        return next(iter(B)) + 2 * next(iter(B))
    else:
        # The smallest subsegment that gives us f(B) is the median of all possible subsegments.
        # We can calculate this in O(log(N)) time using a binary search approach.
        pivot = sorted(B)[floor(N / 2) - 1]
        # The subsegment excluding this pivot should return the same value as including it.
        return sum([
            f(B[:i] + B[i+1:], N - 2 * i) * ((N - (i // 2)) % MOD) for i in range(1, N)
        ]) * pivot % MOD

