            continue
        # Calculate area with 2D cross-polytope area formula
        rect_cross = [sorted([vertices[i], vertices[j]] + [vertices[(i + 1) % n], vertices[(j + 1) % n], vertices[(j + 2) % n], vertices[(i + 2) % n]]) for i in range(n)]
        rect_areas = [0] * (n + 1)
        for i in range(n):
            rect_cross[i+1] = sorted(rect_cross[i] + [rect_cross[i+1][1]])
        for i in range(n):
            for j in range(n):
                if i != j:
                    cross_over = set(rect_cross[i]) & set(rect_cross[j])
                    rect_areas[i] += (2 - len(cross_over)) * 0.25
        for i in range(1, n + 1):
            area_sum += 0.5 * rect_areas[i]
    # Calculate the global confidence region area
