def find_largest_circle(n, m, red_points, blue_points):
    blue_heap = []
    dp = {}
    distances = []

    for point in blue_points:
        dist1 = (point[0] - red_points[0][0])**2 + (point[1] - red_points[0][1])**2
        for other_point in blue_points:
            if other_point[0] == point[0] and other_point[1] == point[1]:
                continue
            dist2 = (other_point[0] - red_points[0][0])**2 + (other_point[1] - red_points[0][1])**2
            dist = min(dist1, dist2)
            heapq.heappush(blue_heap, (dist + red_points[0][0]*red_points[0][0] + red_points[0][1]*red_points[0][1], dist, other_point))
        if len(blue_heap) > 0:
            heap_dist, _, closest_point = heapq.heappop(blue_heap)
            coord = closest_point[0], closest_point[1]
            heap_coord = red_points[0]
            distances.append((heap_coord[0] - coord[0])**2 + (heap_coord[1] - coord[1])**2)
            dp[(coord, heap_coord)] = heap_dist
    distances.sort()

    i = len(red_points) - 1
    while i >= 0:
        p = red_points[i]
        max_dist = [inf]
        while i >= 0 and dp[(p, red_points[i])] > max_dist[-1]:
            p = red_points[i]
            max_dist.append(dp[(p, red_points[i])])

        if abs(p[0] - red_points[0][0])**2 + abs(p[1] - red_points[0][1])**2 <= sum(abs(dp[(p, other)]) for other in distances):
            return ((dp[(p, red_points[0])])**0.5) / 3 ** 2
        else:
            break

    for i in reversed(range(len(red_points))):
        p = red_points[i]
        dist = (p[0] - red_points[0][0])**2 + (p[1] - red_points[0][1])**2
        best = [inf]
        for other_point in red_points:
            if other_point[0] == p[0] and other_point[1] == p[1]:
                continue
            best.append(dp[(p, other_point)])
        while len(best) - 1 >= 0 and best[-1] > sum(best[:i+1]):
            best.pop()

        if dist <= max(best):
            return ((best[0])**0.5) / 3

    return -1

