    durations = [0] * total_days
    for i in range(total_days):
        for j in range(total_days):
            if day_charging_costs[i] == day_charging_costs[j] and durations[i] < durations[j]:
                durations[i] = durations[j]

    cash_to_pay = 0
    day = 0
    seen_days = [False] * total_days
    while day < total_days:
        cash_to_pay += charge_cost(day_charging_costs[day])
        dur = 0
        while day < total_days and days[day] >= dur:
            seen_days[day] = True
            dur += 1
            day += dur - 1
        day += 1
    for i, cost in enumerate(day_charging_costs):
        if not seen_days[i]:
            cash_to_pay += cost

    return cash_to_pay

